package com.company.lms.web;
import org.springframework.http.ResponseEntity; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasRole('ADMIN')") public class AdminController extends ApiSupport { private final JdbcTemplate db; private final PasswordEncoder passwords; public AdminController(JdbcTemplate db,PasswordEncoder passwords){this.db=db;this.passwords=passwords;}
 @GetMapping("/compliance") public Map<String,Object> compliance(){Map<String,Object> m=db.queryForMap("SELECT (SELECT COUNT(*) FROM users WHERE role='employee' AND is_active) total_employees,(SELECT COUNT(*) FROM users WHERE role='trainer' AND is_active) total_trainers,(SELECT COUNT(*) FROM courses WHERE is_published) total_courses,(SELECT COUNT(*) FROM certificates) total_certificates,COUNT(*) total_assignments,COUNT(*) FILTER(WHERE completed_at IS NOT NULL) completed_assignments,COUNT(*) FILTER(WHERE due_date<CURRENT_DATE AND completed_at IS NULL) overdue_assignments FROM course_assignments");long total=((Number)m.get("total_assignments")).longValue(),done=((Number)m.get("completed_assignments")).longValue();m.put("company_compliance_rate",total==0?100:Math.round(done*100.0/total));return Map.of("success",true,"metrics",m,"department_stats",db.queryForList("SELECT d.id department_id,d.name department_name,COUNT(DISTINCT u.id) employee_count,COUNT(DISTINCT ca.id) total_assignments,COUNT(DISTINCT ca.id) FILTER(WHERE ca.completed_at IS NOT NULL) completed_assignments,COUNT(DISTINCT ca.id) FILTER(WHERE ca.due_date<CURRENT_DATE AND ca.completed_at IS NULL) overdue_assignments FROM departments d LEFT JOIN users u ON u.department_id=d.id AND u.is_active LEFT JOIN course_assignments ca ON ca.user_id=u.id GROUP BY d.id,d.name ORDER BY d.name"));}
 @GetMapping("/employees") public Map<String,Object> employees(@RequestParam(required=false) String role,@RequestParam(required=false) String search){String sql="SELECT u.id,u.employee_id,u.full_name,u.email,u.role,u.designation,u.is_active,u.created_at,d.name department_name,d.id department_id FROM users u LEFT JOIN departments d ON d.id=u.department_id WHERE 1=1";List<Object> p=new ArrayList<>();if(role!=null){sql+=" AND u.role=?";p.add(role);}if(search!=null){sql+=" AND (u.full_name ILIKE ? OR u.email ILIKE ? OR u.employee_id ILIKE ?)";for(int i=0;i<3;i++)p.add("%"+search+"%");}return ok("employees",db.queryForList(sql+" ORDER BY u.full_name",p.toArray()));}
 @PostMapping("/users") public ResponseEntity<?> create(@RequestBody Map<String,Object>b){if(b.get("full_name")==null||b.get("email")==null||b.get("password")==null)return ResponseEntity.badRequest().body(Map.of("success",false,"message","full_name, email, and password are required."));Map<String,Object> u=db.queryForMap("INSERT INTO users(employee_id,full_name,email,password_hash,role,department_id,designation) VALUES(?,?,?,?,?,?,?) RETURNING id,employee_id,full_name,email,role,department_id,designation,is_active",b.get("employee_id"),b.get("full_name"),b.get("email").toString().toLowerCase(),passwords.encode(b.get("password").toString()),b.getOrDefault("role","employee"),b.get("department_id"),b.get("designation"));return ResponseEntity.status(201).body(Map.of("success",true,"message","User created successfully.","user",u));}
 @PutMapping("/users/{id}") public ResponseEntity<?> update(@PathVariable long id,@RequestBody Map<String,Object>b){return db.update("UPDATE users SET role=COALESCE(?,role),department_id=COALESCE(?,department_id),designation=COALESCE(?,designation),is_active=COALESCE(?,is_active) WHERE id=?",b.get("role"),b.get("department_id"),b.get("designation"),b.get("is_active"),id)==0?ResponseEntity.status(404).body(Map.of("success",false,"message","User not found.")):ResponseEntity.ok(message("User updated successfully."));}
}
